export interface FundTaxation {
  name: string;
  taxationResult: string;
}

export type TaxationType = 'equity' | 'debt' | 'other';

export const getTaxationType = (taxationResult: string): TaxationType => {
  if (taxationResult.includes('20%') && taxationResult.includes('12.50%')) {
    return 'equity';
  }
  if (taxationResult.includes('income tax slab rate')) {
    return 'debt';
  }
  return 'other';
};

